IF NOT EXISTS(SELECT 1 FROM sys.tables WHERE name=N'region_types')
CREATE TABLE region_types(type nvarchar(32) PRIMARY KEY,description nvarchar(255) NOT NULL);
GO
MERGE region_types AS t USING (VALUES
(N'country',N'Sovereign country'),(N'independent_city',N'Province-equivalent city'),
(N'welayat',N'First-level province'),(N'etrap',N'District or city borough'),
(N'city',N'Şäher'),(N'town',N'Şäherçe'),(N'village',N'Oba or OSM-mapped village'),(N'rural_council',N'Geňeşlik')) s(type,description)
ON t.type=s.type WHEN MATCHED THEN UPDATE SET description=s.description
WHEN NOT MATCHED THEN INSERT(type,description) VALUES(s.type,s.description);
GO
IF NOT EXISTS(SELECT 1 FROM sys.tables WHERE name=N'regions')
CREATE TABLE regions(
 id bigint IDENTITY(1,1) PRIMARY KEY,parent_id bigint NULL,
 slug nvarchar(255) NOT NULL UNIQUE,name_tm nvarchar(255) NOT NULL,
 name_en nvarchar(255) NOT NULL,name_ru nvarchar(255),type nvarchar(32) NOT NULL,
 latitude decimal(9,6),longitude decimal(9,6),country_code nchar(2) NOT NULL DEFAULT N'TM',
 verification_status nvarchar(32) NOT NULL DEFAULT N'verified',source_url nvarchar(max),
 source_date date,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
 updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
 CONSTRAINT FK_regions_parent FOREIGN KEY(parent_id) REFERENCES regions(id),
 CONSTRAINT FK_regions_type FOREIGN KEY(type) REFERENCES region_types(type));
GO
IF NOT EXISTS(SELECT 1 FROM sys.tables WHERE name=N'region_aliases')
CREATE TABLE region_aliases(
 id bigint IDENTITY(1,1) PRIMARY KEY,region_id bigint NOT NULL,
 alias nvarchar(255) NOT NULL,language nvarchar(8) NOT NULL,alias_type nvarchar(32) NOT NULL,
 normalized_alias nvarchar(255) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
 CONSTRAINT UQ_region_alias UNIQUE(region_id,alias),
 CONSTRAINT FK_alias_region FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE CASCADE);
GO
CREATE OR ALTER VIEW region_search AS
SELECT r.id,r.parent_id,r.slug,r.name_tm canonical_name,r.type,
 a.alias,a.language,a.alias_type,a.normalized_alias
FROM regions r JOIN region_aliases a ON a.region_id=r.id;
GO
CREATE OR ALTER FUNCTION find_region(@query nvarchar(255))
RETURNS TABLE AS RETURN(
 SELECT id,parent_id,slug,canonical_name,type,alias,language,alias_type
 FROM region_search
 WHERE alias=@query OR normalized_alias=LOWER(@query)
    OR normalized_alias LIKE N'%'+LOWER(@query)+N'%');
GO

IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'idx_regions_parent') CREATE INDEX idx_regions_parent ON regions(parent_id);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'idx_regions_type') CREATE INDEX idx_regions_type ON regions(type);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'idx_alias_normalized') CREATE INDEX idx_alias_normalized ON region_aliases(normalized_alias);
GO

